import sqlite3, json, urllib.request, ssl

db = r"C:\Users\win\.cc-switch\cc-switch.db"
c = sqlite3.connect(db)
row = c.execute(
    "select settings_config from providers where id='f0f05ced-9cdf-44d0-a2b6-00ab3c2e4ab2'"
).fetchone()
cfg = json.loads(row[0])
token = cfg["env"]["ANTHROPIC_AUTH_TOKEN"]
base = cfg["env"]["ANTHROPIC_BASE_URL"].rstrip("/") + "/v1/messages"

models = [
    "claude-sonnet-4-6",
    "claude-sonnet-4-6-20260217",
    "claude-haiku-4-5-20251001",
    "claude-opus-4-6-20260206",
]

ctx = ssl.create_default_context()
for model in models:
    body = json.dumps({
        "model": model,
        "max_tokens": 16,
        "messages": [{"role": "user", "content": "say ok"}],
    }).encode()
    req = urllib.request.Request(
        base + "?beta=true",
        data=body,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
            "anthropic-version": "2023-06-01",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=20, context=ctx) as r:
            print(model, "OK", r.status)
    except Exception as e:
        err = str(e)
        if hasattr(e, "read"):
            try:
                err = e.read().decode()[:300]
            except Exception:
                pass
        print(model, "FAIL", err[:300])

